import itertools

def get_next_states(state, n):
    next_states = set()
    # Rule 1: 2x2 with exactly three infected
    for i in range(n - 1):
        for j in range(n - 1):
            indices = [(i, j), (i + 1, j), (i, j + 1), (i + 1, j + 1)]
            infected = [state[r * n + c] for r, c in indices]
            if sum(infected) == 3:
                new_state = list(state)
                for idx, (r, c) in enumerate(indices):
                    if infected[idx] == 0:
                        new_state[r * n + c] = 1
                        break
                next_states.add(tuple(new_state))
    # Rule 2: 2x2 with exactly two infected
    for i in range(n - 1):
        for j in range(n - 1):
            indices = [(i, j), (i + 1, j), (i, j + 1), (i + 1, j + 1)]
            infected = [state[r * n + c] for r, c in indices]
            if sum(infected) == 2:
                new_state = list(state)
                for r, c in indices:
                    new_state[r * n + c] = 1 - new_state[r * n + c]
                next_states.add(tuple(new_state))
    return next_states

def can_reach_all(n, k):
    target = tuple([1] * (n * n))
    for initial_state in itertools.product([0, 1], repeat=n * n):
        if sum(initial_state) != k:
            continue

        visited = set()
        queue = [initial_state]
        visited.add(initial_state)
        found = False
        while queue:
            curr = queue.pop(0)
            if curr == target:
                found = True
                break
            for next_s in get_next_states(curr, n):
                if next_s not in visited:
                    visited.add(next_s)
                    queue.append(next_s)
        if not found:
            return False
    return True

for n in [2, 3]:
    for k in range(1, n*n + 1):
        res = can_reach_all(n, k)
        print(f"n={n}, k={k}: {res}")

